import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';

type Row = [label: string, value: string];

/**
 * A plain verification slip generated by this app from a provider lookup.
 * It is labelled as such and is not an official government document.
 */
export async function buildSlip(args: { title: string; reference: string; issuedAt: Date; rows: Row[]; footer?: string }): Promise<Uint8Array> {
  const pdf = await PDFDocument.create();
  const page = pdf.addPage([595, 842]);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const font = await pdf.embedFont(StandardFonts.Helvetica);
  const ink = rgb(0.055, 0.1, 0.075);
  const green = rgb(0.043, 0.478, 0.294);
  const grey = rgb(0.36, 0.42, 0.38);

  page.drawRectangle({ x: 0, y: 842 - 90, width: 595, height: 90, color: ink });
  page.drawText('Verify Hub', { x: 40, y: 842 - 50, size: 22, font: bold, color: rgb(1, 1, 1) });
  page.drawText(args.title, { x: 40, y: 842 - 74, size: 12, font, color: rgb(0.72, 0.78, 0.74) });

  let y = 842 - 140;
  for (const [label, value] of args.rows) {
    page.drawText(label.toUpperCase(), { x: 40, y, size: 8, font: bold, color: grey });
    page.drawText(value || '-', { x: 40, y: y - 16, size: 13, font: bold, color: ink });
    page.drawLine({ start: { x: 40, y: y - 28 }, end: { x: 555, y: y - 28 }, thickness: 0.5, color: rgb(0.89, 0.91, 0.88) });
    y -= 52;
  }

  page.drawText(`Reference ${args.reference}  ·  Generated ${args.issuedAt.toISOString().slice(0, 16).replace('T', ' ')} UTC`, {
    x: 40, y: 70, size: 9, font, color: grey,
  });
  page.drawText(args.footer ?? 'Generated by Verify Hub from a data-provider lookup. Not an official government document.', {
    x: 40, y: 54, size: 8, font, color: green,
  });
  return pdf.save();
}
